/**
 * Trenumi design tokens → CSS custom properties + a Tailwind preset.
 *
 * Source of truth is the Figma file, not this repo. `tokens.json` is exported
 * from it; everything below is derived and must not be hand-edited.
 *
 * Dark mode is built separately, from config.dark.js, because
 * Style Dictionary merges every source into one tree: feeding it both files here
 * would let the dark values overwrite the light ones inside :root. `npm run
 * tokens` runs both builds.
 */

const CSS_HEADER = [
  'Trenumi design tokens.',
  'Generated by Style Dictionary — do not edit by hand.',
  'Change the value in Figma, re-export tokens.json, run `npm run tokens`.'
];

/**
 * Tailwind preset. Values point at the CSS custom properties rather than at hex
 * literals, so a Tailwind class and a hand-written rule both follow
 * [data-theme="dark"] without a second colour map.
 */
function tailwindPreset({ dictionary }) {
  const groups = {
    colors: [], backgroundColor: [], textColor: [], borderColor: [],
    spacing: [], borderRadius: [], fontSize: [], lineHeight: [], fontWeight: []
  };

  for (const token of dictionary.allTokens) {
    const [head, ...rest] = token.path;
    const cssVar = `var(--${token.name})`;

    if (token.$type === 'color') {
      // Full map, so every token is reachable however it is named.
      groups.colors.push([token.path.join('.'), cssVar]);

      // Primitives are also exposed without the `color.` prefix, so the brand
      // palette reads as bg-brand-lime rather than bg-color-brand-lime.
      if (head === 'color') groups.colors.push([rest.join('.'), cssVar]);

      // A token whose last segment names the property it paints is mapped to
      // that property, so `action.primary.bg` becomes `bg-action-primary`
      // instead of the stuttering `bg-action-primary-bg`.
      const last = token.path[token.path.length - 1];
      const stem = token.path.slice(0, -1).join('.');
      if (last === 'bg' && stem) groups.backgroundColor.push([stem, cssVar]);
      else if (last === 'fg' && stem) groups.textColor.push([stem, cssVar]);
      else if (last === 'border' && stem) groups.borderColor.push([stem, cssVar]);
      else if (head === 'text') groups.textColor.push([rest.join('.'), cssVar]);
      else if (head === 'surface') groups.backgroundColor.push([rest.join('.'), cssVar]);
      else if (head === 'bg') groups.backgroundColor.push([rest.join('.'), cssVar]);
      else if (head === 'border') groups.borderColor.push([rest.join('.'), cssVar]);
      else if (head === 'icon') groups.textColor.push(['icon-' + rest.join('.'), cssVar]);
    }
    else if (head === 'space') groups.spacing.push([rest.join('.'), cssVar]);
    else if (head === 'radius') groups.borderRadius.push([rest.join('.'), cssVar]);
    else if (head === 'font' && rest[0] === 'size') groups.fontSize.push([rest.slice(1).join('.'), cssVar]);
    else if (head === 'font' && rest[0] === 'line-height') groups.lineHeight.push([rest.slice(1).join('.'), cssVar]);
    else if (head === 'font' && rest[0] === 'style') groups.fontWeight.push([rest.slice(1).join('.'), String(token.$value)]);
  }

  /**
   * Dotted keys become the nested objects Tailwind expects.
   *
   * A key can be both a leaf and a branch — `nav.bg` and `nav.selected.bg` both
   * want `nav`. Tailwind's own answer is DEFAULT, so `bg-nav` paints the bar and
   * `bg-nav-selected` paints the pill.
   */
  const nest = (pairs) => {
    const out = {};
    const leaf = (obj, key, value) => {
      if (obj[key] && typeof obj[key] === 'object') obj[key].DEFAULT = value;
      else obj[key] = value;
    };
    const branch = (obj, key) => {
      if (typeof obj[key] === 'string') obj[key] = { DEFAULT: obj[key] };
      else obj[key] = obj[key] || {};
      return obj[key];
    };
    for (const [path, value] of pairs) {
      const parts = path.split('.');
      let cur = out;
      for (let i = 0; i < parts.length - 1; i++) cur = branch(cur, parts[i]);
      leaf(cur, parts[parts.length - 1], value);
    }
    return out;
  };

  const theme = Object.fromEntries(
    Object.entries(groups).filter(([, p]) => p.length).map(([name, p]) => [name, nest(p)])
  );

  return [
    '// Trenumi design tokens as a Tailwind preset.',
    '// Generated by Style Dictionary — do not edit by hand.',
    '// Values resolve to CSS custom properties, so Tailwind classes follow the',
    '// active theme without a second colour map.',
    'module.exports = {',
    '  theme: {',
    '    extend: ' + JSON.stringify(theme, null, 2).split('\n').join('\n    '),
    '  }',
    '};',
    ''
  ].join('\n');
}

export default {
  usesDtcg: true,
  source: ['tokens.json'],
  hooks: { formats: { 'js/tailwind-preset': tailwindPreset } },
  platforms: {
    css: {
      transformGroup: 'css',
      buildPath: 'src/styles/',
      files: [{
        destination: 'tokens.css',
        format: 'css/variables',
        options: { outputReferences: true, selector: ':root', fileHeader: () => CSS_HEADER }
      }]
    },
    tailwind: {
      transformGroup: 'css',
      buildPath: 'src/styles/',
      files: [{ destination: 'tailwind-preset.cjs', format: 'js/tailwind-preset' }]
    }
  }
};
